/*  Normalises the caller's input. Anything that stops the run early is
    returned as a result item rather than thrown, so the caller can branch on it  */
const SUPPORTED_ENTITY_TYPES = ['courseTemplate', 'learningPath'];
const inputs = $('When Called').all().map(i => i.json);
const input = inputs[0] || {};
const entityType = String(input.entityType || '').trim();
const entityId = String(input.entityId || '').trim();
const tagNames = [...new Set(String(input.tagsCsv || '').split(',').map(s => s.trim()).filter(Boolean))];

const result = { success: false, message: '', entityType, entityId, tagNames, learningTagIds: [], createdTagNames: [], errors: [] };

let error = '';
if (inputs.length !== 1) {
  error = 'Expected one item per call but received ' + inputs.length + '. Set the calling Execute Workflow node to run once for each item.';
} else if (!SUPPORTED_ENTITY_TYPES.includes(entityType)) {
  error = 'entityType must be one of ' + SUPPORTED_ENTITY_TYPES.join(', ') + ' but was "' + entityType + '".';
} else if (!entityId) {
  error = 'entityId is required.';
}

if (error) {
  return [{ json: Object.assign(result, { proceed: false, message: error, errors: [error] }) }];
}
if (!tagNames.length) {
  return [{ json: Object.assign(result, { proceed: false, success: true, message: 'No tags supplied, so nothing was changed.' }) }];
}
return [{ json: Object.assign(result, { proceed: true }) }];

const result = Object.assign({}, $json);
delete result.proceed;
return { json: result };

/*  Lists the tags that do not exist yet. Always returns at least one item so
    exactly one branch of the next IF runs and Collect Tag Ids runs once  */
const tagNames = $('Split Tags').all().map(i => i.json.tagName);
const lookups = $('Find Tag').all().map(i => i.json);
const missing = tagNames.filter((tagName, index) => {
  const response = lookups[index] || {};
  if (Array.isArray(response.errors) && response.errors.length) {
    return false;
  }
  const edges = ((response.data || {}).learningTags || {}).edges || [];
  return edges.length === 0;
});
if (!missing.length) {
  return [{ json: { nothingToCreate: true } }];
}
return missing.map(tagName => ({ json: { tagName } }));

const formatErrors = (response, fieldErrors) => {
  const messages = [];
  (response.errors || []).forEach(e => messages.push(e.message || JSON.stringify(e)));
  (fieldErrors || []).forEach(e => messages.push((e.label ? e.label + ': ' : '') + (e.message || JSON.stringify(e))));
  return messages;
};
const input = $('Validate Input').first().json;
const tagNames = $('Split Tags').all().map(i => i.json.tagName);
const lookups = $('Find Tag').all().map(i => i.json);
const tagIds = {};
const tagErrors = [];
const createdTagNames = [];

tagNames.forEach((tagName, index) => {
  const response = lookups[index] || {};
  const errors = formatErrors(response);
  if (errors.length) {
    tagErrors.push('Looking up tag "' + tagName + '" failed: ' + errors.join('; '));
    return;
  }
  const edges = ((response.data || {}).learningTags || {}).edges || [];
  if (edges.length) {
    tagIds[tagName] = edges[0].node.id;
  }
});

if ($('Create Tag').isExecuted) {
  const toCreate = $('Find Missing Tags').all().map(i => i.json.tagName);
  const created = $('Create Tag').all().map(i => i.json);
  toCreate.forEach((tagName, index) => {
    const response = created[index] || {};
    const createResult = ((response.data || {}).learningTags || {}).create || {};
    const errors = formatErrors(response, createResult.errors);
    const tag = (createResult.learningTags || [])[0];
    if (errors.length || !tag || !tag.id) {
      tagErrors.push('Creating tag "' + tagName + '" failed: ' + (errors.join('; ') || 'no ID was returned'));
      return;
    }
    tagIds[tagName] = tag.id;
    createdTagNames.push(tagName);
  });
}

return [{ json: {
  entityType: input.entityType,
  entityId: input.entityId,
  tagNames,
  learningTagIds: tagNames.map(tagName => tagIds[tagName]).filter(Boolean),
  createdTagNames,
  tagErrors
} }];

const MUTATIONS = {
  courseTemplate: 'mutation AddCourseTemplateTags($input: CourseTemplateAddTagsInput!) { courseTemplate { addTags(input: $input) { courseTemplate { id name } errors { label message value } } } }',
  learningPath: 'mutation AddLearningPathTags($input: LearningPathAddTagsInput!) { learningPaths { addTags(input: $input) { learningPath { id name } errors { label message value } } } }'
};
const ID_FIELDS = { courseTemplate: 'courseTemplateId', learningPath: 'learningPathId' };
const input = { learningTagIds: $json.learningTagIds };
input[ID_FIELDS[$json.entityType]] = $json.entityId;
return { json: { query: MUTATIONS[$json.entityType], variables: { input } } };

const formatErrors = (response, fieldErrors) => {
  const messages = [];
  (response.errors || []).forEach(e => messages.push(e.message || JSON.stringify(e)));
  (fieldErrors || []).forEach(e => messages.push((e.label ? e.label + ': ' : '') + (e.message || JSON.stringify(e))));
  return messages;
};
const ROOT_FIELDS = { courseTemplate: 'courseTemplate', learningPath: 'learningPaths' };
const collected = $('Collect Tag Ids').first().json;
const errors = collected.tagErrors.slice();

/*  Reached from Add Tags, or straight from Can Add Tags? when a tag could
    not be found or created (in which case addTags was not called)  */
if (!errors.length) {
  const response = $input.first().json;
  const addTags = ((response.data || {})[ROOT_FIELDS[collected.entityType]] || {}).addTags || {};
  formatErrors(response, addTags.errors).forEach(message => errors.push('addTags failed: ' + message));
}

const success = errors.length === 0;
return [{ json: {
  success,
  message: success
    ? 'Added ' + collected.learningTagIds.length + ' tag(s) to ' + collected.entityType + ' ' + collected.entityId + '.'
    : 'Tags were not added. See errors.',
  entityType: collected.entityType,
  entityId: collected.entityId,
  tagNames: collected.tagNames,
  learningTagIds: collected.learningTagIds,
  createdTagNames: collected.createdTagNames,
  errors
} }];
